import {
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
  TextureNode,
  Object3D
} from 'three/webgpu';

export default function createNode(config, ctx) {
  // --- geometry ---
  const aspect = 512 / 320; // from atlas source rect
  const width = 1.6;        // ~aspect * 1.0 height
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // --- texture ---
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  // Optional: use a TextureNode for TSL compliance (not required here)
  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: THREE.DoubleSide, // visible from both sides if needed
    transparent: true
  });

  // --- mesh ---
  const mesh = new Mesh(geometry, material);
  mesh.position.set(-3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // --- user data ---
  mesh.userData = {
    handlers: {}, // no interactions
    cleanup: () => {
      geometry.dispose();
      material.dispose();
      if (texture) texture.dispose();
      // No GSAP timelines to kill
    }
  };

  return mesh;
}
